-- Converted: GRANT SELECT, INSERT ON TABLE sales.payment TO operator converted to GRANT SELECT, INSERT ON TABLE SALES.PAYMENT TO ROLE OPERATOR.
-- Reason: Snowflake grants object privileges to roles, so the grantee needs the ROLE keyword. The privilege list is kept exactly as in the source (no ALL, no PUBLIC, no WITH GRANT OPTION).
GRANT SELECT, INSERT ON TABLE SALES.PAYMENT TO ROLE OPERATOR;

-- Converted: GRANT SELECT ON TABLE sales.audit_log TO auditor converted to GRANT SELECT ON TABLE SALES.AUDIT_LOG TO ROLE AUDITOR.
-- Reason: Snowflake grants object privileges to roles, so the grantee needs the ROLE keyword. The privilege is kept at SELECT only.
GRANT SELECT ON TABLE SALES.AUDIT_LOG TO ROLE AUDITOR;

-- Converted: GRANT EXECUTE PROCEDURE ON sales.add_payment TO operator converted to GRANT USAGE ON PROCEDURE SALES.ADD_PAYMENT(<argument types>) TO ROLE OPERATOR, run from an anonymous Snowflake Scripting block that reads the procedure's argument signature from SHOW PROCEDURES.
-- Reason: Snowflake's equivalent of Teradata EXECUTE PROCEDURE is USAGE on the procedure, and it must name the full argument-type signature, which the batch does not include (sales.add_payment has no columns/parameters in its signature). Reading the signature from the catalog avoids guessing types. The block fails with an explicit error unless exactly one ADD_PAYMENT procedure exists in SALES, so the grant never targets the wrong overload.
EXECUTE IMMEDIATE $$
DECLARE
  v_count INTEGER DEFAULT 0;
  v_signature VARCHAR;
  e_signature_not_unique EXCEPTION (-20001, 'Expected exactly one procedure SALES.ADD_PAYMENT; grant not applied.');
BEGIN
  SHOW PROCEDURES LIKE 'ADD_PAYMENT' IN SCHEMA SALES;
  SELECT COUNT(*),
         MAX(REPLACE(REPLACE(TRIM(SPLIT_PART("arguments", ' RETURN ', 1)), '[', ''), ']', ''))
    INTO :v_count, :v_signature
    FROM TABLE(RESULT_SCAN(LAST_QUERY_ID()))
   WHERE "name" = 'ADD_PAYMENT';
  IF (v_count <> 1) THEN
    RAISE e_signature_not_unique;
  END IF;
  -- Converted: The privilege is applied with GRANT USAGE ON PROCEDURE SALES.<signature> TO ROLE OPERATOR.
  -- Reason: USAGE is the only privilege Snowflake defines for executing a procedure. The signature comes from the catalog rather than user input, and identifiers cannot be bound with USING in GRANT, so the statement text is concatenated.
  EXECUTE IMMEDIATE 'GRANT USAGE ON PROCEDURE SALES.' || v_signature || ' TO ROLE OPERATOR';
  RETURN 'GRANT USAGE ON PROCEDURE SALES.' || v_signature || ' TO ROLE OPERATOR';
END;
$$;

-- Converted: GRANT SELECT ON TABLE sales.customer_accounts TO reader converted to GRANT SELECT ON VIEW SALES.CUSTOMER_ACCOUNTS TO ROLE READER.
-- Reason: sales.customer_accounts is a view, so the Snowflake object type is VIEW. Snowflake grants object privileges to roles, so the grantee needs the ROLE keyword. The privilege is kept at SELECT only.
GRANT SELECT ON VIEW SALES.CUSTOMER_ACCOUNTS TO ROLE READER;

-- Converted: GRANT SELECT ON TABLE sales.account_payments TO reader converted to GRANT SELECT ON VIEW SALES.ACCOUNT_PAYMENTS TO ROLE READER.
-- Reason: sales.account_payments is a view, so the Snowflake object type is VIEW. Snowflake grants object privileges to roles, so the grantee needs the ROLE keyword. The privilege is kept at SELECT only.
GRANT SELECT ON VIEW SALES.ACCOUNT_PAYMENTS TO ROLE READER;
